// DenaivamCitadel — scouts dominate the start, then a base in the center with towers
// around it (built from DenaivamFortress; no imports).
// All-skills assault strategy + scout combat micro + energy gathering micro.
// Upload this one file as-is.

// =====================================================================
// BUILD ORDER — edit this.
// Items are bought top to bottom; `number` is how many of that item to buy.
// If an item only lacks energy, the bot saves up for it before buying anything later.
// If an item is impossible right now (not enough crystal, needs a second Base, unit
// cap, no free build site, too late in the game...), it is skipped and the next item is
// tried; the skipped item stays owed and is bought as soon as it becomes possible.
// Crystal items come first: as soon as the bank holds the crystal for an owed item
// (Soldier, Base, upgrades...), that item is bought before anything else in the list,
// and if it is then only short of energy the bot waits for the energy. While owed items
// wait for crystal, the bot spends only energy, so the crystal is kept for them.
// While everything left is blocked, and once the whole list has been bought, the bot
// decides what to build by itself (see FREE MODE below) until the game ends.
// Rules follow the arena README (README.md): upgrades are per unit, once per unit.
//
// Items:
//   "eWorker"           worker that gathers energy
//   "cWorker"           worker that gathers crystals
//   "WallWorker"        worker that walls off the enemy's crystals
//   "FortressWorker"    worker that walls itself in at the center (see CENTER FORTRESS).
//                       If the list contains it, the fortress starts when you buy it and
//                       only the fortress workers you buy are used; without it the bot
//                       picks one itself at FORTRESS_START_TICK.
//   "Soldier"           fighter unit (needs 15 crystals)
//   "Scout"             scout; the bot gives it a job (crystal raid, crystal guard,
//                       energy raid, then base attack)
//   "CrystalRaiderScout" scout that raids crystals on the enemy side
//   "CrystalGuardScout" scout that guards crystals on our side
//   "EnergyRaiderScout" scout that hunts enemy energy workers
//   "BaseAttackScout"   scout that goes straight for enemy bases
//   "Tower"             defensive turret near our base
//   "OffensiveTower"    turret near the crystals (needs a second Base first)
//   "CenterTower"       turret around the center base (needs the center Base first), placed
//                       just outside the final circle where it covers the most of it
//   "Base"              expansion base near the map center
//   "ScoutUpgrade"      upgrade one scout per `number` (15 C each): HP 5 -> 10 and
//                       speed 2 -> 4; crystal-hunting scouts are upgraded first
//   "SoldierUpgrade"    upgrade one soldier per `number` (20 C each): turrets ignore it
//   "WallUpgrade"       upgrade one wall per `number` (50 E each): wall HP x2
// Item names are not case-sensitive. Unknown items are skipped (there is no cargo,
// attack or armor upgrade in the arena).
// =====================================================================
const BUILD_ORDER = [
  { item: "eWorker", number: 2 },
  // Scouts dominate the start: crystal raiders kill the enemy's first crystal workers.
  { item: "CrystalRaiderScout", number: 4 },
  { item: "eWorker", number: 2 },
  { item: "cWorker", number: 2 },
  { item: "Scout", number: 8 },
  { item: "eWorker", number: 2 },
  // The center base (100 E + 50 C) as soon as its crystal is banked, then towers around it.
  { item: "Base", number: 1 },
  { item: "CenterTower", number: 4 },
  { item: "ScoutUpgrade", number: 4 },
  { item: "Soldier", number: 4 },
];
// Build-order item name -> internal role used by the strategy code below.
const BUILD_ITEMS = {
  eworker: "eWorker", cworker: "cWorker",
  wallworker: "wallBuilderWorker", wallbuilderworker: "wallBuilderWorker",
  fortressworker: "fortressWorker", centerwallworker: "fortressWorker",
  soldier: "Soldier", fighter: "Soldier",
  scout: "Scout",
  crystalraiderscout: "cRaiderScout", craiderscout: "cRaiderScout",
  crystalguardscout: "cRaiderScoutHome", craiderscouthome: "cRaiderScoutHome",
  energyraiderscout: "eRaiderScout", eraiderscout: "eRaiderScout",
  baseattackscout: "baseAttackerScout", baseattackerscout: "baseAttackerScout",
  tower: "defensiveTower", defensivetower: "defensiveTower",
  offensivetower: "offensiveTower", centertower: "centerTower",
  base: "Base",
  scoutupgrade: "ScoutUpgrade", scoutspeedupgrade: "ScoutUpgrade",
  soldierupgrade: "SoldierUpgrade", fighterupgrade: "SoldierUpgrade",
  wallupgrade: "WallUpgrade",
};
// Jobs handed to generic "Scout" purchases, filled in this order; the rest attack bases.
const SCOUT_JOBS = [["cRaiderScout", 3], ["cRaiderScoutHome", 3], ["eRaiderScout", 3]];

// FREE MODE (after the build order, or while everything left in it is blocked).
// Priorities: stop the enemy taking crystals, build soldiers, take over the center.
// Crystal-hunting scouts the bot keeps alive: [job, how many].
const FREE_MODE_CRYSTAL_SCOUTS = [["cRaiderScout", 4], ["cRaiderScoutHome", 3], ["eRaiderScout", 2]];
const FREE_MODE_CENTER_TOWERS = 2;  // turrets over the center crystals (needs a second Base)
const FREE_MODE_PUSH_SOLDIERS = 12; // soldiers hold the center until there are this many,
                                    // then they march on the enemy base

// SOLDIER SWARMS: scouts gang up on a lonely enemy soldier (30 HP, kills a 5 HP scout per
// hit; an upgraded 10 HP scout survives one hit). Before attacking, the bot simulates the
// fight with the scouts it has nearby and the open tiles around the soldier, and only
// attacks if the soldier dies and we lose at most SWARM_MAX_LOSSES scouts.
// Rough guide: 8 plain scouts in the open lose 5; 6-8 upgraded scouts lose only 2-3.
const SWARM_ENABLED = true;
const SWARM_RADIUS = 12;        // scouts within this many tiles of the soldier can join
const SWARM_WITH_BASE_ATTACKERS = true; // base-attack scouts nearby join swarms too
const SWARM_MAX_LOSSES = 5;     // most scouts we accept losing for one soldier
const SWARM_LONELY_RADIUS = 4;  // "lonely": no other enemy soldier this close to it
const SWARM_TURRET_RADIUS = 5;  // ...and no enemy turret this close (turrets shred scouts)

// SPOTTER AND ENERGY RAID: one scout watches the enemy base area from outside turret
// range and records its defence (soldiers, turrets, scouts) and its energy workers.
// When our scouts can overwhelm that defence, ALL scouts raid the enemy energy nodes and
// kill every energy worker they find, then go back to their normal jobs.
// Overwhelm check: expected scout losses while killing the workers (soldiers kill about
// a scout per tick, turrets one every 2-3 ticks) must stay under RAID_MAX_LOSS_SHARE of
// our scouts. Upgraded scouts (10 HP) count as tougher.
const SPOTTER_ENABLED = true;
const RAID_ENABLED = true;
const RAID_MIN_SCOUTS = 10;        // never raid with fewer scouts than this
const RAID_MAX_LOSS_SHARE = 0.4;   // raid only if we expect to lose at most 40% of them
const RAID_INTEL_TICKS = 40;       // how long a sighting near the enemy base stays valid
const RAID_ABORT_SHARE = 0.4;      // call the raid off below 40% of the starting scouts

// CENTER FORTRESS: one worker walls itself in at the map center so that, whatever happens
// elsewhere, it is still alive in the final safe circle (radius 3 around 19.5,19.5) at
// tick 500, where the player with more living units wins.
// - The worker's spot is the map center (one of the 4 tiles around 19.5,19.5), where the
//   death circle ends; the fortress and the worker's final cell are built around it.
// - Walls go up in square rings around an open FORTRESS_SIZE x FORTRESS_SIZE area with the
//   worker's spot in the middle, outer ring first, then the ring behind it.
//   Turrets shoot at range 4: with size 7 or more the innermost ring is at least 4 tiles
//   from the worker, so no enemy can stand or build a turret in range of it. Smaller
//   fortresses are cheaper and faster to close, but a turret built right outside can
//   reach the worker. Each extra layer shields the ring inside it.
//   Walls needed: size 5 -> 24 + 32 (2 layers), 7 -> 32 + 40, 9 -> 40 + 48.
// - One gate per ring, on our side, stays open until FORTRESS_SEAL_TICK so our units can
//   retreat inside; then the worker closes it. Destroyed walls are rebuilt.
// - With spare energy the walls are upgraded (50 E each: HP 60 -> 120), outer ring first;
//   the zone also damages walls outside the shrinking circle in the last ~25 ticks.
const FORTRESS_ENABLED = false;       // off in DenaivamCitadel: walls would take the center
                                      // the base and towers need (set true to combine them)
const FORTRESS_START_TICK = 200;      // when the bot picks a fortress worker itself (only
                                      // if BUILD_ORDER has no "FortressWorker" item)
// At tick 500 the side with MORE LIVING UNITS wins. The death circle ends at radius 3
// around (19.5,19.5): 32 tiles where everything survives (soldiers, 30 HP, also survive
// up to ~5 tiles out). Size 6 makes the inside of the fortress exactly that area
// (tiles 17..22), so the whole army can shelter in it.
const FORTRESS_SIZE = 6;              // open space inside the walls: 6 = 6x6 tiles (4 = 4x4, ...)
const FORTRESS_LAYERS = 2;            // wall rings around that space, built outer ring first
const FORTRESS_RETREAT_TICK = 360;    // the whole army retreats into the fortress from here
const ENDGAME_PATH_BUDGET = 110;      // route searches per tick during the retreat (normal: 60)
const FORTRESS_GATE_SIDES = 2;        // gates on the 1 or 2 sides facing our base (units come
                                      // from both directions when our base is diagonal to it)
const FORTRESS_GATE_WIDTH = 6;        // the gate: this many tiles of each such side stay
                                      // open until sealing (a 1-tile gate cannot let a whole army
                                      // in in time; capped at FORTRESS_SIZE)
const FORTRESS_SEAL_TICK = 392;       // close the gates once the army is inside (with the cell
                                      // on, the gates close 15 ticks before the cell instead)
const FORTRESS_CELL = "auto";         // the worker's own 3x3 cell: true, false, or "auto" = only
                                      // for small fortresses (size < 5); in a shelter its walls
                                      // would take 8 of the 32 safe tiles from our units
const FORTRESS_CELL_TICK = 360;       // the worker walls itself in: it stands on its spot and
                                      // builds all 8 tiles around itself (no walking needed),
                                      // a cell closed by walls alone for the death circle.
                                      // Before 375, when the army starts retreating to the
                                      // center and would stand on the cell tiles.
const FORTRESS_EMERGENCY_CELL = true; // if the center is dangerous (the worker got hit, one
                                      // was killed, or 2+ enemy soldiers close to it), wall
                                      // itself in right away instead of finishing the rings
const FORTRESS_WORKERS = 1;           // workers building and living in the fortress
const FORTRESS_SEALERS = 6;           // shelter mode: workers inside that help seal the gates
const FORTRESS_UPGRADE_RESERVE = 100; // energy kept for other spending before the end game
const FORTRESS_MAX_LOST = 2;          // replace a killed fortress worker at most this often
const FORTRESS_MIN_ECONOMY = 3;       // never take a worker if fewer would stay gathering

// CITADEL: a base in the center with towers around it.
// - "Base" is placed as close to the map center as possible (within 4 tiles).
// - "CenterTower" turrets go around it, CITADEL_TOWER_MIN..MAX_RADIUS from the center:
//   just outside the final circle (radius 3), so they take none of the 32 tiles our units
//   need at the end, yet close enough to survive the last ticks of zone damage (a turret
//   has 50 HP; at 4.5 tiles it takes 24). Each new one covers the most final-circle tiles
//   not yet covered (turret range 4: 4 damage per tick to the weakest enemy unit).
// - A base inside the final circle keeps spawning units until the end (normal spawning
//   stops at tick 375): units spawned there stand in the safe circle and count at tick 500.
const CITADEL_TOWERS = 4;             // center towers free mode keeps alive
const CITADEL_TOWER_MIN_RADIUS = 3.3; // tower distance from the map center (19.5,19.5)
const CITADEL_TOWER_MAX_RADIUS = 4.6;
const CITADEL_LATE_SPAWN = true;      // the center base spawns until the end of the game
